target.css:
:root {
  --ink: #173f4a;
  --water: #217d82;
  --foam: #e4f3ef;
  --paper: #fffdf7;
  --sun: #f0b45b;
  --coral: #d85d4c;
}

.canoe-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 16px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 15px;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--water);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  background: var(--sun);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.trip-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  overflow: hidden;
  background: var(--foam);
  border-radius: 10px;
}

.detail {
  padding: 12px 13px;
  border-left: 1px solid var(--water);
}

.detail:first-child {
  border-left: 0;
}

.detail-label,
.paddler p span {
  display: block;
  color: var(--water);
  font-size: 11px;
  font-weight: 700;
}

.detail-value {
  display: block;
  margin-top: 3px;
  font-size: 15px;
}

.checkout-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 15px;
}

.paddler {
  display: flex;
  align-items: center;
  gap: 9px;
}

.avatar {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  background: var(--water);
  border-radius: 50%;
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.paddler p {
  margin: 0;
  line-height: 1.25;
}

.paddler p strong {
  display: block;
  font-size: 14px;
}

.return-button {
  padding: 8px 12px;
  background: var(--coral);
  border: 0;
  border-radius: 8px;
  color: var(--paper);
  font-size: 13px;
  font-weight: 700;
}

